import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadRobotoMono = makeLoadFont('RobotoMono');

const { fontFamily: robotoMonoFamily } = loadRobotoMono();



export type TypingEffectProps = Record<string, any>;

const TypingEffect: React.FC<TypingEffectProps> = ({
  backgroundColor = "#050505",
  transparentBackground = false,
  durationInSeconds = 5,
  textToType = "We're not your marketing agency..",
  textColor = "#e0e0e0",
  cursorColor = "#ff2a5f",
  typingSpeedFrames = 3,
  startDelayFrames = 15,
}) => {
  const frame = useCurrentFrame();
  const { width } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Calculate how many characters should be visible at the current frame
  const activeFrameCount = Math.max(0, frame - startDelayFrames);
  const charsToShow = Math.floor(activeFrameCount / typingSpeedFrames);
  
  // Extract the visible substring
  const visibleText = textToType.slice(0, charsToShow);
  
  // Blinking cursor logic (blinks every 12 frames)
  const cursorOpacity = Math.floor(frame / 12) % 2 === 0 ? 1 : 0;

  // Responsive sizing based on standard 1080x1920 mobile portrait width
  const fontSize = width * 0.08;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: robotoMonoFamily,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          width: "85%", // Constrained width to respect safe zones
          textAlign: "left",
          fontSize: fontSize,
          color: textColor,
          fontWeight: 600,
          lineHeight: 1.4,
          whiteSpace: "pre-wrap",
          overflowWrap: "break-word",
          display: "inline-block",
        }}
      >
        <span>{visibleText}</span>
        <span
          style={{
            color: cursorColor,
            opacity: cursorOpacity,
            transition: "none", // Strict rule: No CSS transitions
            marginLeft: "4px",
            display: "inline-block",
            transform: "translateY(12%)", // Align cursor nicely with text baseline
            fontWeight: 800,
          }}
        >
          |
        </span>
      </div>
    </AbsoluteFill>
  );
};

export default TypingEffect;